<script setup lang="ts">import{reactive,ref,onMounted,onUnmounted}from'vue';import{api,errorMessage}from'../api';import PageHeader from'../components/PageHeader.vue';import Modal from'../components/Modal.vue';import DataTable from'../components/DataTable.vue';import StatusBadge from'../components/StatusBadge.vue';import{Plus}from'lucide-vue-next';const rows=ref<any[]>([]),open=ref(false),error=ref('');const form=reactive({document:'',legal_name:'',trade_name:'',state_registration:'',city_ibge_code:'',municipal_registrations:[]});const cols=[{key:'legal_name',label:'Razão social'},{key:'trade_name',label:'Fantasia'},{key:'document',label:'CNPJ/CPF'},{key:'state_registration',label:'Inscrição estadual'},{key:'city_ibge_code',label:'Município IBGE'},{key:'status',label:'Situação'}];async function load(){rows.value=(await api.get('/legal-entities')).data}async function save(){try{await api.post('/legal-entities',form);open.value=false;await load()}catch(e){error.value=errorMessage(e)}}onMounted(()=>{load();window.addEventListener('tenant-changed',load)});onUnmounted(()=>window.removeEventListener('tenant-changed',load))
</script><template><PageHeader title="Empresas e CNPJs" subtitle="Cadastre matrizes, filiais, inscrições estaduais e municipais"><button class="btn primary" @click="open=true"><Plus :size="16"/>Nova empresa</button></PageHeader><section class="panel"><DataTable :columns="cols" :rows="rows"><template #cell-status="{value}"><StatusBadge :status="value"/></template></DataTable></section><Modal :open="open" title="Cadastrar empresa" @close="open=false"><form class="form-grid" @submit.prevent="save"><label>CNPJ/CPF<input v-model="form.document" required/></label><label>Razão social<input v-model="form.legal_name" required/></label><label>Nome fantasia<input v-model="form.trade_name"/></label><label>Inscrição estadual<input v-model="form.state_registration"/></label><label>Código IBGE<input v-model="form.city_ibge_code"/></label><div v-if="error" class="alert danger span-2">{{error}}</div><div class="form-actions span-2"><button class="btn primary">Salvar</button></div></form></Modal></template>
